namespace {
    namespace types_ = rush2::car_types;
    constexpr int old_types = 22;
    constexpr int new_types = types_::types;

    // The per-type tables' copies (include/car_types.h, tools/rush2049/cartypes.py layout). The per-player tables (3
    // rows in Rush 2) get rows for players 3 and 4 (src/players4.cpp) and 5 to 8 (an online race,
    // docs/online.md#eight-players), which start as copies of players 1 and 2's. The race reads a human car's row by its
    // player number + 1 (car +0x7E0): with 5 rows, players 5 to 8 read the next table's rows, and the race setup's fill
    // of their rows wrote over the next table's computer car row.
    struct Table {
        uint32_t old_base;
        uint32_t new_base;
        int size; // bytes per entry
        int rows; // in Rush 2's table
    };
    constexpr int player_table_rows = types_::player_rows;
    constexpr int new_rows(const Table& t) {
        return t.rows == 3 ? player_table_rows : t.rows;
    }
    constexpr int old_row(int row) {
        return row < 3 ? row : 1 + (row - 1) % 2;
    }
    constexpr std::array<Table, std::size(types_::tables)> make_tables() {
        std::array<Table, std::size(types_::tables)> out{};
        for (size_t i = 0; i < out.size(); i++) {
            const types_::Table& t = types_::tables[i];
            out[i] = { t.old_base, types_::table(t.old_base), t.size, t.rows };
        }
        return out;
    }
    constexpr auto tables = make_tables();

    // Race per-car arrays the car select also indexes by preview id (player * types + type): 44 entries moved to
    // types_::preview_ids (cartypes.py id_layout; us.toml relocates their users).
    struct IdArray {
        uint32_t old_base;
        uint32_t new_base;
        uint32_t stride;
    };
    constexpr int old_ids = types_::old_ids;
    constexpr std::array<IdArray, std::size(types_::id_arrays)> make_id_arrays() {
        std::array<IdArray, std::size(types_::id_arrays)> out{};
        for (size_t i = 0; i < out.size(); i++) {
            const types_::IdArray& a = types_::id_arrays[i];
            out[i] = { a.old_base, types_::id_array(a.old_base), a.stride };
        }
        return out;
    }
    constexpr auto id_arrays = make_id_arrays();

    // Asset tables with room for the extra cars' files (2049: 0x71 + n, California Speed: 0x80 + n), and the car
    // select's per-player car list and carousel (us.toml points the game at these).
    constexpr uint32_t old_asset_offsets = 0x800C185C;
    constexpr uint32_t old_asset_sizes = 0x8001CD64;
    constexpr uint32_t asset_offsets = types_::asset_offsets;
    constexpr uint32_t asset_sizes = types_::asset_sizes;
    constexpr int old_assets = 0x71;
    constexpr int first_car_asset = 0x71;
    constexpr int parts_asset = rush2::car2049::parts_asset;
    static_assert(first_car_asset + car_count <= parts_asset && parts_asset < rush2::car2049::first_calspeed_asset);
    std::vector<std::array<float, 3>> part_centers;
    constexpr uint32_t car_slot_size = 0x8001CF28; // largest car asset (0xD1F0); func_800A37F4 allocates each slot

    // Per-type 16-byte tables: car boxes {front, rear, half width, height} (0x800CAC6C, 22 entries) and a second table
    // (0x800CADCC, 23 entries: entry 22 is a special case func_80059D24 picks), moved to every type.
    constexpr uint32_t old_boxes = 0x800CAC6C;
    constexpr uint32_t boxes = types_::boxes;
    constexpr uint32_t old_table16 = 0x800CADCC;
    constexpr uint32_t table16 = types_::table16;

    constexpr uint32_t car_list_counts = 0x803CB398; // s16 per player
    constexpr uint32_t car_names = types_::car_names; // part name prefixes of the extra types ("CAR1".."CAR13", ...)
    constexpr uint32_t name_table = types_::table(types_::name_pointers); // type -> part name prefix

    // Per-car options the player record keeps for each type (record + 0x584 + type * 13); types 22-72 live in side
    // slots, one per record, so the Controller Pak record keeps its layout.
    constexpr uint32_t record_block = 0x584;
    constexpr int block_size = 13;
    constexpr int durability_byte = 10;              // /100 = the weight (func_800B24AC)
    constexpr int engine_byte = 6;                   // ENGINE (func_800B2554)
    constexpr uint32_t side_slots = types_::side_slots;
    constexpr int side_slot_size = types_::side_slot_size;
    constexpr int max_side_slots = types_::max_side_slots;
    // Player records, 0x6C0 bytes each: the active players' (func_80097FCC) and the Controller Pak image's (4 paks of
    // 0x2200 bytes, src/rush2049/track2049_records.cpp). Side slots are keyed by record address in these ranges.
    constexpr uint32_t record_size = 0x6C0;
    constexpr uint32_t player_records = 0x8010D740, player_records_end = 0x8010D740 + 8 * 0x6C0;
    constexpr uint32_t pak_records = 0x8004B220, pak_records_end = 0x8004B220 + 4 * 0x2200;
    bool in_save_area(uint32_t at) {
        return (at >= player_records && at < player_records_end) || (at >= pak_records && at < pak_records_end);
    }

    // Physics: Rush 2's descriptor pointers (0x800C07BC, indexed through the type -> index table) move to a larger
    // copy; the 2049 cars' descriptors (Rush 2's 0xEC-byte layout, converted from 2049's 0xB4-byte ones as
    // tools/rush2049/cars.py does) follow Rush 2's 11, then California Speed's (src/calspeed/calspeed_cars.cpp), with
    // copies of the tire curves they point at.
    constexpr uint32_t old_desc_ptrs = 0x800C07BC;
    constexpr uint32_t desc_ptrs = types_::desc_ptrs;
    constexpr int rush2_descs = 11;
    constexpr uint32_t tire_curves = types_::tire_curves; // 2049 front, rear: 6 floats each
    constexpr uint32_t descs = types_::descs;             // 13 x 0xEC
    constexpr uint32_t desc_size = types_::desc_size;
    // Relocated per-type tables.
    constexpr uint32_t t_desc_index = types_::table(types_::desc_index), t_preload = types_::table(types_::preload),
                       t_mass = types_::table(types_::mass), t_inertia = types_::table(types_::inertia),
                       t_yaw_inertia = types_::table(types_::yaw_inertia), t_drive = types_::table(types_::drive),
                       t_weight = types_::table(types_::weight), t_engine = types_::table(types_::engine),
                       t_torque = types_::table(types_::torque), t_susp = types_::table(types_::suspension),
                       t_tires = types_::table(types_::tires);
    // TIRES row values: Rush 2's 0-10 (S0 D0 .. S2 D2, 9 HALF OFFRD, 10 FULL OFFRD), then the two tires of Rush 2049
    // that Rush 2 has no match for, SLICKS and PRO SLICKS (2049's RADIALS, ALL TERRAIN and OFF ROAD are Rush 2's street
    // sets, HALF OFFRD and FULL OFFRD: the same off-road factor and rear grip). Every car offers all of them.
    constexpr int slicks = 11, pro_slicks = 12;
    constexpr int tires49[5] = { 4, slicks, pro_slicks, 9, 10 };     // RADIALS, SLICKS, PRO SLICKS, ALL TERRAIN, OFF ROAD
    constexpr int tires49_count = 5;
    constexpr int handling_count = 3;                                // NORMAL, ADVANCED, EXTREME

    // Rush 2049 main code/data (rush2::rom2049::Segment::Main, at 0x80086A50).
    constexpr uint32_t main49_vram = 0x80086A50;
    struct Main49 {
        std::vector<uint8_t> d;
        uint32_t w(uint32_t vram) const {
            size_t o = vram - main49_vram;
            return (uint32_t(d[o]) << 24) | (uint32_t(d[o + 1]) << 16) | (uint32_t(d[o + 2]) << 8) | d[o + 3];
        }
        float f(uint32_t vram) const {
            uint32_t v = w(vram);
            float r;
            memcpy(&r, &v, 4);
            return r;
        }
        int8_t b(uint32_t vram) const { return (int8_t)d[vram - main49_vram]; }
    };

    std::mutex side_mutex;

    // Paint: each car's asset copy keeps the 2049 palette at a fixed offset; it is rewritten as the pristine palette
    // times the main colour whenever the game builds the car's Rush 2 palette (func_8008582C).
    struct Paint {
        uint32_t texture_table = 0;          // file offset of the texture records
        uint32_t texture_count = 0;
        uint32_t first_texels = 0;           // file offset of the first texture's texels (sanity check)
        uint32_t palette = 0;                // file offset of the palette
        std::vector<uint8_t> colours;        // pristine RGBA5551 palette
        // A Dreamcast disc's car: its paint jobs' body textures (rush2::rom2049::SourceTexture::job), each job a
        // full set with its own pattern, in place of the N64's paint ramps. rush2_car49_paint copies job MAIN COLOR %
        // jobs into the car (the car select shows MAIN COLOR as STYLE, src/rush2049/wings_menu.cpp).
        struct JobTexture {
            uint32_t pristine = 0;              // file offsets of its texels and of their damaged copy (0: none)
            uint32_t damaged = 0;
            std::vector<std::vector<uint8_t>> texels, scuffed; // per job
        };
        std::vector<JobTexture> job_textures;
        std::vector<uint32_t> job_rgb;
        JobTexture* job_texture(uint32_t texels) {
            for (JobTexture& t : job_textures) {
                if (t.pristine == texels) return &t;
            }
            return nullptr;
        }
        // Denting: the body's vertices (file offsets) and their pristine positions.
        std::vector<uint32_t> vertices;
        std::vector<std::array<int16_t, 3>> rest;
        std::vector<float> hood;                // each vertex's share of the hood's fold (0-1), see body_hood
        // The sheen layers' vertices (track2049::sheen_parts) at each body vertex's position, dented with it.
        std::vector<std::vector<uint32_t>> mirrors;
        float extent[3] = { 1.0f, 1.0f, 1.0f }; // half width, height, half length
        // Damage textures: the body's texture loads, each serving one panel (0 FR, 1 FL, 2 RR, 3 RL, 4 top), whose
        // G_SETTIMG reads the pristine texels or their scuffed copy by that panel's damage.
        // A California Speed car's tail light textures also have lit copies of both (0: none), drawn while its brake
        // lights are on (rush2_calspeed_brake_lights).
        struct DamageLoad {
            uint32_t at;        // file offset of the G_SETTIMG
            uint32_t pristine;  // file offsets of the texels
            uint32_t damaged;
            int panel;
            uint32_t lit = 0, lit_damaged = 0;
        };
        std::vector<DamageLoad> damage_loads;
        // Rocket ZX exhaust flames (ROKTFLAMEG1-3): their vertices as modelled (at the origin, pointing back), and the
        // tile sizes of the scrolled flame texture's load list.
        struct Flame {
            std::vector<uint32_t> vertices;
            std::vector<std::array<int16_t, 3>> rest;
        };
        std::vector<Flame> flames;
        std::vector<std::pair<uint32_t, uint32_t>> flame_tiles; // G_SETTILESIZE offset, its w1
        std::vector<uint32_t> flame_lists;  // file offsets of the flames' display lists
        std::vector<uint32_t> body_lists;   // file offsets of the body's (FRAME1) display lists, every LOD
        std::vector<uint32_t> hood_lists;   // the same for the hood camera's hood (H0_L, H2_L: 2049's CARnHOOD)
        // A Rush 2 type drawn as one body (set_body_car): Rush 2 paints it, so it has no colours of its own, and its
        // textures' scuffed copies are given (pristine texel offset -> copy).
        bool body = false;
        std::map<uint32_t, std::vector<uint8_t>> given_scuffs;
        // A California Speed car (set_calspeed_car): a body painted by California Speed's painter on its own palette
        // (colours), with its textures scuffed along that palette's ramps.
        bool calspeed = false;
        // Its first texture record's name: every mod container is laid out alike (the same texture table and texels
        // offsets), so a body is told apart by this name (src/car_mods.cpp names the records after the car).
        char first_name[16] = {};
        // A mod car's color schemes (rush2::car2049::scheme_marker): each block's start and end marker (file offsets)
        // in every list of the car, so rush2_car49_paint can show one scheme per car.
        struct SchemeBlock {
            uint32_t start, end;
            int scheme;
        };
        std::vector<SchemeBlock> scheme_blocks;
        int schemes = 0;
    };
    Paint paints[car_count];
    // Rush 2 types drawn as one body (car mods, src/car_mods.cpp) and California Speed's (src/calspeed/calspeed_cars.cpp).
    Paint bodies[types];
    constexpr uint32_t car_banks = types_::car_banks; // s16 texture bank per preview id (moved from 0x800D9D40)
    constexpr uint32_t bank_table = 0x80119220;     // [bank] = texture records, count
    constexpr int paint_ramps[3] = { 32, 64, 96 }; // COLOR 1-3 (main, accent, stripe colour)
    constexpr uint32_t car_palettes = types_::car_palettes; // per preview id, stride 0x18 (moved from 0x800D97FC)
    std::map<uint32_t, int> side_slot_of;            // record address -> side slot index
    std::map<uint32_t, int> selected_type_of;        // address of a record's selected-type byte -> full type
    // An online race's other players' 2049 car options (set_guest_side_block): their profiles are copies outside the
    // save area (src/online/online_game.cpp), whose getters read these blocks, never saved. In spare RDRAM after the
    // online race's profile copies (src/controls_menu.cpp's map).
    constexpr uint32_t guest_side_slots = types_::guest_side_slots;
    constexpr int max_guests = types_::max_guests;
    std::map<uint32_t, int> guest_slot_of;            // guest profile address -> guest slot index

    std::atomic_bool cars_option = true;

    // Rush 2049's setup tables (docs/rush2049_research/cars.md �9), for applying a player's car options.
    struct Setup49 {
        bool loaded = false;
        float torque[9][3];      // 0x801110C4 [ENGINE][HANDLING]
        float trans[3][11];      // 0x801116D0 [HANDLING]: +1 mass, +2 torque, +3 gear ratio, +7 rear grip factors
        float gears[6];          // 0x80110EBC gear set 0
        float rear_grip[5];      // 0x8011121C [TIRES]
        float k_mass, k_frame0, k_frame1, k_yaw;
        float mass[car_count], inertia[car_count], yaw[car_count];
        int handling[car_count], tires[car_count], frame[car_count]; // the drones' setup (rows B, D, E)
        float frame_weight[6];   // 0x80111274 [FRAME]
        int colours[car_count][3]; // 0x80111604 / 0x80111648 / 0x8011168C: each car's COLOR 1-3 (func_800BB140)
        int rims[car_count];       // 0x8011157C: each car's TIRE RIMS (RIM01 + value, as in Rush 2)
        int engine[car_count];     // 0x80111080: the drones' ENGINE (row C)
        float wheel_scale[2][car_count]; // 0x801112DC / 0x801113E0 row 0: each car's front, rear wheel model scale
        rush2::car2049::EngineLayer engine_sounds[9][2]; // 0x8010FD80 [ENGINE]
    };
    Setup49 setup49;
    bool is_2049(int type) {
        return type >= first_type && type < end_type && setup49.loaded;
    }

    bool cars_available() {
        return cars_option.load(std::memory_order_relaxed) && rush2::wings::rom_available();
    }

    void copy_entry(uint8_t* rdram, const Table& t, int row, int from_type, int to_type) {
        uint32_t src = t.old_base + (old_row(row) * old_types + from_type) * t.size;
        uint32_t dst = t.new_base + (row * new_types + to_type) * t.size;
        for (int i = 0; i < t.size; i++) {
            MEM_B(0, (int32_t)(dst + i)) = MEM_B(0, (int32_t)(src + i));
        }
    }
}

// Called once at boot, before any menu or race reads the tables.
namespace {
    constexpr uint32_t old_prefixes = 0x800C64C4;   // texture name prefix per type ("TRK_", ...)
    constexpr uint32_t prefixes = types_::prefixes;   // every type
    constexpr uint32_t no_prefix = types_::no_prefix; // "R49X_": matches no texture
    constexpr uint32_t engine_labels = 0x80225800;  // the ENGINE names, 16 bytes each (car options)
    constexpr uint32_t tire_labels = 0x802258C0;    // 2049's TIRES names, 16 bytes each
    constexpr const char* tire_names[tires49_count] = { "RADIALS", "SLICKS", "PRO SLICKS", "ALL TERRAIN", "OFF ROAD" };
    using rush2::car2049::engine_levels;
}

void rush2::car2049::init_tables(uint8_t* rdram) {
    for (int t = 0; t < types; t++) {
        MEM_W(0, (int32_t)(prefixes + t * 4)) = t < rush2_types ? MEM_W(0, (int32_t)(old_prefixes + t * 4)) : (int32_t)no_prefix;
    }
    auto put_label = [&](uint32_t at, const std::string& label) {
        for (size_t j = 0; j < 16; j++) {
            MEM_B(0, (int32_t)(at + j)) = j < label.size() ? label[j] : 0;
        }
    };
    for (int i = 0; i < engine_levels; i++) {
        put_label(engine_labels + i * 16, rush2::car2049::engine_name(i));
    }
    for (int i = 0; i < tires49_count; i++) {
        put_label(tire_labels + i * 16, tire_names[i]);
    }
    const char* none = "R49X_";
    for (int i = 0; i <= 5; i++) {
        MEM_B(0, (int32_t)(no_prefix + i)) = none[i];
    }
    for (const Table& t : tables) {
        for (int row = 0; row < new_rows(t); row++) {
            for (int type = 0; type < new_types; type++) {
                // Type 22 and the 2049 types start as copies of the Pickup until the 2049 cars' data is filled in.
                copy_entry(rdram, t, row, type < old_types ? type : 0, type);
            }
        }
    }
    for (int t = 0; t < types; t++) {
        int from = t < rush2_types ? t : 0;
        for (int i = 0; i < 16; i++) {
            MEM_B(0, (int32_t)(boxes + t * 16 + i)) = MEM_B(0, (int32_t)(old_boxes + from * 16 + i));
            MEM_B(0, (int32_t)(table16 + t * 16 + i)) =
                MEM_B(0, (int32_t)(old_table16 + (t == rush2_types ? rush2_types : from) * 16 + i));
        }
    }
    for (const IdArray& a : id_arrays) {
        for (uint32_t i = 0; i < old_ids * a.stride; i++) {
            MEM_B(0, (int32_t)(a.new_base + i)) = MEM_B(0, (int32_t)(a.old_base + i));
        }
    }
}

